import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "@clerk/clerk-react";
import ProgressHeader from "./components/ProgressHeader";
import WaterAnimation from "./components/WaterAnimation";
import ProgressIndicator from "./components/ProgressIndicator";
import HelpModal from "./components/HelpModal";
import CancelConfirmationModal from "./components/CancelConfirmationModal";
import BottomTabNavigation from "../../components/ui/BottomTabNavigation";
import { showErrorToast, showWarningToast } from "../../components/ui/NotificationToast";
import { useDispenseFlow } from "../water-dispensing-control/FlowProvider";
import TelemetryStatusCard from "../water-dispensing-control/components/TelemetryStatusCard";
import {
  DEFAULT_PULSES_PER_LITER,
  getTargetPulseCount,
  pulsesToLiters,
  pulsesToProgress,
  sanitizePulsesPerLiter,
} from "../water-dispensing-control/telemetry";

const API = import.meta.env.VITE_API_URL;
const CLERK_JWT_TEMPLATE = "aquaqr-api";

function money(n) {
  return new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
    minimumFractionDigits: 2,
  }).format(n);
}

const PULSE_COMPLETION_PROGRESS = 99;
const RESET_COMPLETION_PROGRESS = 99.5;

export default function FillingProgress() {
  const navigate = useNavigate();
  const location = useLocation();
  const { getToken, isLoaded, isSignedIn, userId } = useAuth();

  const flow = useDispenseFlow();
  const lastTx = flow?.lastTx;
  const telemetry = flow?.telemetry;
  const setTelemetryEnabled = flow?.setTelemetryEnabled;
  const currentPulsesPerLiter = flow?.pulsesPerLiter;
  const completeDispense = flow?.completeDispense;
  const cancelActiveSession = flow?.cancelActiveSession;
  const [recoveredTx, setRecoveredTx] = useState(null);
  const [isRecoveringTx, setIsRecoveringTx] = useState(true);
  const routeTx = location.state?.tx || null;

  const tx = lastTx || recoveredTx;

  useEffect(() => {
    setRecoveredTx(null);
    setIsRecoveringTx(true);
  }, [userId]);

  useEffect(() => {
    if (tx) {
      setIsRecoveringTx(false);
      return;
    }

    if (!isLoaded) return;

    if (!isSignedIn) {
      setIsRecoveringTx(false);
      return;
    }

    let cancelled = false;

    const recoverActiveDispense = async () => {
      try {
        const token = await getToken({ template: CLERK_JWT_TEMPLATE });
        const res = await fetch(`${API}/api/dispense/active`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await res.json().catch(() => null);
        if (cancelled) return;

        if (res.ok && data?.active && data?.tx && (data.nextPath === "/filling-progress" || data.stageCode === "06" || data.stageCode === "07")) {
          if (routeTx?.txId && data.tx?.txId && routeTx.txId !== data.tx.txId) {
            setIsRecoveringTx(false);
            return;
          }
          setRecoveredTx({
            ...data.tx,
            machineId: data.tx.machineId || data.machineId,
            location: data.tx.location || data.machineLocation,
            pulsesPerLiter: data.tx.pulsesPerLiter || currentPulsesPerLiter || DEFAULT_PULSES_PER_LITER,
          });
          setIsRecoveringTx(false);
          return;
        }

        setIsRecoveringTx(false);
      } catch {
        if (!cancelled) setIsRecoveringTx(false);
      }
    };

    recoverActiveDispense();

    return () => {
      cancelled = true;
    };
  }, [currentPulsesPerLiter, getToken, isLoaded, isSignedIn, routeTx?.txId, tx]);

  useEffect(() => {
    if (tx || isRecoveringTx) return;
    navigate("/water/choose", { replace: true });
  }, [isRecoveringTx, tx, navigate]);

  if (!tx) return null;

  return <FillingProgressView tx={tx} />;
}

function FillingProgressView({ tx }) {
  const navigate = useNavigate();
  const { getToken, isLoaded, isSignedIn } = useAuth();
  const flow = useDispenseFlow();
  const telemetry = flow?.telemetry;
  const setTelemetryEnabled = flow?.setTelemetryEnabled;
  const currentPulsesPerLiter = flow?.pulsesPerLiter;
  const completeDispense = flow?.completeDispense;
  const cancelActiveSession = flow?.cancelActiveSession;
  const sendStageCommand = flow?.sendStageCommand;
  const pollInputs = flow?.pollInputs;

  const liters = Number(tx.liters) || 0;
  const pricePerLiter = Number(tx.pricePerLiter) || 0;
  const totalCost = (tx.amountCents ?? Math.round(liters * pricePerLiter * 100)) / 100;
  const startPulseCount = Number.parseInt(tx.startPulseCount, 10) || 0;
  const pulsesPerLiter = sanitizePulsesPerLiter(
    tx.pulsesPerLiter ?? currentPulsesPerLiter,
    DEFAULT_PULSES_PER_LITER,
  );
  const targetPulseCount = getTargetPulseCount(liters, pulsesPerLiter);

  const [flowRate, setFlowRate] = useState(0);
  const [isHelpModalOpen, setIsHelpModalOpen] = useState(false);
  const [isCancelModalOpen, setIsCancelModalOpen] = useState(false);
  const [isCancelling, setIsCancelling] = useState(false);
  const [isDispensing, setIsDispensing] = useState(true);
  const [isUiPaused, setIsUiPaused] = useState(false);
  const [pauseSnapshot, setPauseSnapshot] = useState(null);
  const [pauseCommandLoading, setPauseCommandLoading] = useState("");
  const [completionStatus, setCompletionStatus] = useState("");
  const [displayTelemetry, setDisplayTelemetry] = useState(telemetry || null);
  const [progressSnapshot, setProgressSnapshot] = useState({
    progress: 0,
    dispensedLiters: 0,
    dispensedPulseCount: 0,
  });
  const lastTelemetrySampleRef = useRef(null);
  const completionScheduledRef = useRef(false);
  const mountedRef = useRef(false);
  const completionSnapshotRef = useRef({
    sawFilling: false,
    sawComplete: false,
    progress: 0,
    dispensedLiters: 0,
    dispensedPulseCount: 0,
  });

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  useEffect(() => {
    setTelemetryEnabled?.(true);
    return () => setTelemetryEnabled?.(false);
  }, [setTelemetryEnabled]);

  const currentPulseCount = Number.parseInt(telemetry?.flowmeterPulses, 10);
  const dispensedPulseCount = useMemo(() => {
    if (!Number.isFinite(currentPulseCount) || currentPulseCount < 0) return 0;
    if (currentPulseCount >= startPulseCount) return currentPulseCount - startPulseCount;
    return currentPulseCount;
  }, [currentPulseCount, startPulseCount]);

  const dispensedLiters = useMemo(
    () => Math.min(liters, pulsesToLiters(dispensedPulseCount, pulsesPerLiter)),
    [dispensedPulseCount, liters, pulsesPerLiter],
  );

  const progress = useMemo(() => {
    return pulsesToProgress(dispensedPulseCount, targetPulseCount);
  }, [dispensedPulseCount, targetPulseCount]);
  const currentStageCode = telemetry?.currentStageCode || "";
  const isTelemetryComplete = currentStageCode === "07";

  const finishAndCharge = useCallback(async (options = {}) => {
    if (completionScheduledRef.current) return;
    if (typeof completeDispense !== "function") return;

    const snapshot = completionSnapshotRef.current;
    const liveDispensedPulseCount = Math.max(
      snapshot.dispensedPulseCount,
      dispensedPulseCount,
      options.dispensedPulseCount || 0,
    );
    const finalDispensedLiters = Math.max(
      snapshot.dispensedLiters,
      dispensedLiters,
      options.dispensedLiters || 0,
      liters,
    );
    const finalDispensedPulseCount = Math.max(
      liveDispensedPulseCount,
      targetPulseCount,
      options.dispensedPulseCount || 0,
    );

    completionScheduledRef.current = true;
    setIsDispensing(false);
    setCompletionStatus(options.status || "Finalizando...");

    try {
      const completedTx = await completeDispense(tx, {
        dispensedLiters: finalDispensedLiters,
        dispensedPulseCount: finalDispensedPulseCount,
        pulsesPerLiter,
      });
      if (!mountedRef.current) return;

      navigate("/transaction-complete", {
        state: {
          tx: completedTx,
          dispensedLiters: finalDispensedLiters,
          dispensedPulseCount: finalDispensedPulseCount,
          pulsesPerLiter,
        },
      });
    } catch (error) {
      if (!mountedRef.current) return;
      completionScheduledRef.current = false;
      setCompletionStatus("");

      if (error?.code === "INSUFFICIENT_FUNDS") {
        navigate("/balance-recharge", {
          state: {
            returnTo: "/transaction-complete",
            requiredAmount: error.requiredAmount,
            tx,
            dispensedLiters: finalDispensedLiters,
            dispensedPulseCount: finalDispensedPulseCount,
            pulsesPerLiter,
            fromInsufficientBalance: true,
          },
        });
        return;
      }

      showErrorToast(error?.message || "No se pudo finalizar");
    }
  }, [
    completeDispense,
    dispensedLiters,
    dispensedPulseCount,
    liters,
    navigate,
    pulsesPerLiter,
    targetPulseCount,
    tx,
  ]);

  useEffect(() => {
    const snapshot = completionSnapshotRef.current;
    const reachedTargetPulses =
      targetPulseCount > 0 && dispensedPulseCount >= targetPulseCount;
    const isFillingTelemetry =
      currentStageCode === "06"
      || telemetry?.pumpOn
      || telemetry?.fillValveOn
      || progress > 0
      || dispensedPulseCount > 0
      || reachedTargetPulses;

    if (isFillingTelemetry) {
      snapshot.sawFilling = true;
    }

    if (isTelemetryComplete || reachedTargetPulses) {
      snapshot.sawComplete = true;
      snapshot.sawFilling = true;
    }

    const nextProgress = (isTelemetryComplete || reachedTargetPulses)
      ? 100
      : Math.max(snapshot.progress, progress);
    const nextDispensedLiters = (isTelemetryComplete || reachedTargetPulses)
      ? Math.max(snapshot.dispensedLiters, dispensedLiters, liters)
      : Math.max(snapshot.dispensedLiters, dispensedLiters);
    const nextDispensedPulseCount = Math.max(snapshot.dispensedPulseCount, dispensedPulseCount);

    if (
      nextProgress !== snapshot.progress
      || nextDispensedLiters !== snapshot.dispensedLiters
      || nextDispensedPulseCount !== snapshot.dispensedPulseCount
    ) {
      snapshot.progress = nextProgress;
      snapshot.dispensedLiters = nextDispensedLiters;
      snapshot.dispensedPulseCount = nextDispensedPulseCount;
      setProgressSnapshot({
        progress: nextProgress,
        dispensedLiters: nextDispensedLiters,
        dispensedPulseCount: nextDispensedPulseCount,
      });
    }
  }, [
    currentStageCode,
    dispensedLiters,
    dispensedPulseCount,
    isTelemetryComplete,
    liters,
    progress,
    targetPulseCount,
    telemetry?.fillValveOn,
    telemetry?.pumpOn,
  ]);

  useEffect(() => {
    if (!telemetry) return;

    const isDispensingTelemetry =
      telemetry.currentStageCode === "06"
      || telemetry.pumpOn
      || telemetry.fillValveOn
      || (Number.parseInt(telemetry.flowmeterPulses, 10) || 0) > startPulseCount;

    if (isDispensing || progress < 100 || isDispensingTelemetry) {
      setDisplayTelemetry(telemetry);
    }
  }, [isDispensing, progress, startPulseCount, telemetry]);

  const remainingTime = useMemo(() => {
    if (flowRate <= 0) return null;
    return Math.max(0, Math.ceil(((liters - dispensedLiters) / flowRate) * 60));
  }, [dispensedLiters, flowRate, liters]);

  useEffect(() => {
    if (!isDispensing) return;
    if (!Number.isFinite(currentPulseCount) || currentPulseCount < 0) return;

    const now = Date.now();
    const previous = lastTelemetrySampleRef.current;

    if (
      previous
      && currentPulseCount >= previous.pulseCount
      && now > previous.seenAt
    ) {
      const deltaPulses = currentPulseCount - previous.pulseCount;
      const deltaSeconds = (now - previous.seenAt) / 1000;
      if (deltaPulses > 0 && deltaSeconds > 0) {
        const deltaLiters = pulsesToLiters(deltaPulses, pulsesPerLiter);
        const nextFlowRate = (deltaLiters / deltaSeconds) * 60;
        setFlowRate(Number(nextFlowRate.toFixed(2)));
      }
    }

    lastTelemetrySampleRef.current = {
      pulseCount: currentPulseCount,
      seenAt: now,
    };
  }, [currentPulseCount, isDispensing, pulsesPerLiter]);

  useEffect(() => {
    const snapshot = completionSnapshotRef.current;
    const liveProgress = Math.max(snapshot.progress, progress);
    const liveDispensedPulseCount = Math.max(snapshot.dispensedPulseCount, dispensedPulseCount);
    const hasTargetPulseCount = targetPulseCount > 0;
    const sawFilling =
      snapshot.sawFilling
      || currentStageCode === "06"
      || liveProgress > 0
      || liveDispensedPulseCount > 0;
    const reachedTargetPulses =
      hasTargetPulseCount && liveDispensedPulseCount >= targetPulseCount;
    const completedByResetToIdle =
      currentStageCode === "00"
      && sawFilling
      && (liveProgress >= RESET_COMPLETION_PROGRESS || reachedTargetPulses);
    const completedByPulses =
      sawFilling
      && (liveProgress >= PULSE_COMPLETION_PROGRESS || reachedTargetPulses);
    const completedByStage = isTelemetryComplete || snapshot.sawComplete;

    if (!completedByStage && !completedByResetToIdle && !completedByPulses) return;

    finishAndCharge({
      dispensedLiters: Math.max(snapshot.dispensedLiters, dispensedLiters, liters),
      dispensedPulseCount: Math.max(liveDispensedPulseCount, targetPulseCount),
    });
  }, [currentStageCode, dispensedLiters, dispensedPulseCount, finishAndCharge, isTelemetryComplete, liters, progress, targetPulseCount]);

  useEffect(() => {
    if (!isLoaded || !isSignedIn) return undefined;
    if (completionScheduledRef.current) return undefined;

    let cancelled = false;
    let checking = false;

    const refreshAfterResume = async () => {
      if (checking || completionScheduledRef.current) return;
      checking = true;

      try {
        const nextTelemetry = await pollInputs?.({ force: true }).catch(() => null);
        if (cancelled || completionScheduledRef.current) return;

        if (nextTelemetry?.currentStageCode === "07") {
          finishAndCharge({ status: "Finalizando..." });
          return;
        }

        const token = await getToken({ template: CLERK_JWT_TEMPLATE });
        if (!token) return;

        const res = await fetch(`${API}/api/dispense/active`, {
          headers: { Authorization: `Bearer ${token}` },
          cache: "no-store",
        });
        const data = await res.json().catch(() => null);
        if (cancelled || completionScheduledRef.current) return;

        if (res.ok && data?.active && data?.stageCode === "07") {
          finishAndCharge({ status: "Finalizando..." });
          return;
        }

        const backendTxId = data?.tx?.txId;
        const sameTx = !backendTxId || !tx?.txId || backendTxId === tx.txId;
        if (res.ok && sameTx && (!data?.active || data?.tx?.status === "COMPLETED")) {
          finishAndCharge({ status: "Sincronizando dispensado terminado..." });
        }
      } finally {
        checking = false;
      }
    };

    const handleResume = () => {
      if (typeof document !== "undefined" && document.visibilityState !== "visible") return;
      refreshAfterResume();
    };

    handleResume();
    document.addEventListener("visibilitychange", handleResume);
    window.addEventListener("focus", handleResume);
    window.addEventListener("pageshow", handleResume);

    return () => {
      cancelled = true;
      document.removeEventListener("visibilitychange", handleResume);
      window.removeEventListener("focus", handleResume);
      window.removeEventListener("pageshow", handleResume);
    };
  }, [finishAndCharge, getToken, isLoaded, isSignedIn, pollInputs, tx?.txId]);

  const liveDisplayProgress = Math.max(progress, progressSnapshot.progress);
  const liveDisplayDispensedLiters = Math.max(dispensedLiters, progressSnapshot.dispensedLiters);
  const liveDisplayDispensedPulseCount = Math.max(dispensedPulseCount, progressSnapshot.dispensedPulseCount);
  const displayProgress = isUiPaused && pauseSnapshot
    ? pauseSnapshot.progress
    : liveDisplayProgress;
  const displayDispensedLiters = isUiPaused && pauseSnapshot
    ? pauseSnapshot.dispensedLiters
    : liveDisplayDispensedLiters;
  const displayDispensedPulseCount = isUiPaused && pauseSnapshot
    ? pauseSnapshot.dispensedPulseCount
    : liveDisplayDispensedPulseCount;
  const displayFlowRate = isUiPaused && pauseSnapshot
    ? pauseSnapshot.flowRate
    : flowRate;
  const displayRemainingTime = isUiPaused && pauseSnapshot
    ? pauseSnapshot.remainingTime
    : remainingTime;
  const refundAmount = Number((totalCost * (1 - displayProgress / 100)).toFixed(2));
  const machineConnectionStatus = displayTelemetry?.lastSeenAt
    ? (displayTelemetry.machineOnline ? "connected" : "disconnected")
    : "connecting";

  const handleCancelClick = useCallback(() => {
    if (completionScheduledRef.current || displayProgress >= 100) return;
    setIsCancelModalOpen(true);
  }, [displayProgress]);

  const buildPauseSnapshot = useCallback(() => ({
    progress: liveDisplayProgress,
    dispensedLiters: liveDisplayDispensedLiters,
    dispensedPulseCount: liveDisplayDispensedPulseCount,
    flowRate,
    remainingTime,
  }), [
    flowRate,
    liveDisplayDispensedLiters,
    liveDisplayDispensedPulseCount,
    liveDisplayProgress,
    remainingTime,
  ]);

  const handlePauseFilling = useCallback(async () => {
    if (completionScheduledRef.current || !isDispensing) return;
    if (typeof sendStageCommand !== "function" || pauseCommandLoading) return;

    try {
      setPauseCommandLoading("pause");
      const snapshot = buildPauseSnapshot();
      await sendStageCommand("pausar_llenado");
      await pollInputs?.({ force: true }).catch(() => null);
      setPauseSnapshot(snapshot);
      setIsUiPaused(true);
    } catch (error) {
      showErrorToast(error?.message || "No se pudo pausar el llenado");
    } finally {
      setPauseCommandLoading("");
    }
  }, [
    buildPauseSnapshot,
    isDispensing,
    pauseCommandLoading,
    pollInputs,
    sendStageCommand,
  ]);

  const handleResumeFilling = useCallback(async () => {
    if (completionScheduledRef.current || !isDispensing) return;
    if (typeof sendStageCommand !== "function" || pauseCommandLoading) return;

    try {
      setPauseCommandLoading("resume");
      await sendStageCommand("reanudar_llenado");
      await pollInputs?.({ force: true }).catch(() => null);
      setPauseSnapshot(null);
      setIsUiPaused(false);
    } catch (error) {
      showErrorToast(error?.message || "No se pudo reanudar el llenado");
    } finally {
      setPauseCommandLoading("");
    }
  }, [
    isDispensing,
    pauseCommandLoading,
    pollInputs,
    sendStageCommand,
  ]);

  const handleConfirmCancel = useCallback(async () => {
    if (completionScheduledRef.current || isCancelling) return;

    try {
      setIsCancelling(true);
      const data = await cancelActiveSession?.();
      setIsDispensing(false);
      setIsCancelModalOpen(false);

      const refunded = Number(data?.refundedCents || 0) / 100;
      showWarningToast(
        refunded > 0
          ? `Cancelado. Reembolso ${money(refunded)}.`
          : "Cancelado."
      );

      navigate("/home-dashboard", {
        replace: true,
        state: {
          machineReleased: true,
          reason: "user_cancelled",
          cancelledAt: new Date().toISOString(),
          refundAmount: refunded || refundAmount,
        },
      });
    } catch (error) {
      showErrorToast(error?.message || "No se pudo cancelar el dispensado");
      setIsCancelling(false);
    }
  }, [cancelActiveSession, isCancelling, navigate, refundAmount]);

  useEffect(() => {
    if (!isDispensing || completionScheduledRef.current) return undefined;

    const handlePopState = () => {
      window.history.pushState({ agua24FillingGuard: true }, "", window.location.href);
      setIsCancelModalOpen(true);
    };

    window.history.pushState({ agua24FillingGuard: true }, "", window.location.href);
    window.addEventListener("popstate", handlePopState);
    return () => window.removeEventListener("popstate", handlePopState);
  }, [isDispensing]);

  return (
    <div className="filling-screen min-h-[100dvh] bg-background">
      <ProgressHeader
        machineId={tx.machineId}
        location={tx.location}
        connectionStatus={machineConnectionStatus}
        onCancel={handleCancelClick}
      />

      <main className="filling-content mx-auto flex w-full max-w-lg flex-col gap-2 px-3 py-2 pb-[max(0.5rem,env(safe-area-inset-bottom))]">
        <div className="filling-heading flex min-h-10 items-center justify-center gap-3">
          <WaterAnimation isActive={isDispensing && !isUiPaused} compact />
          <p className="text-sm font-medium text-text-primary">
            {isUiPaused ? "Llenado pausado" : isDispensing ? "Llenando tu garrafón" : "Finalizando llenado"}
          </p>
        </div>

        <ProgressIndicator
          className="filling-indicator"
          progress={displayProgress}
          remainingTime={displayRemainingTime}
          flowRate={displayFlowRate}
          isActive={isDispensing && !isUiPaused}
          dispensedLiters={displayDispensedLiters}
          targetLiters={liters}
          dispensedPulseCount={displayDispensedPulseCount}
          targetPulseCount={targetPulseCount}
          pulsesPerLiter={pulsesPerLiter}
          compact
        />

        <div className="filling-controls w-full rounded-xl border border-sky-200 bg-white p-2 shadow-sm">
          {!isUiPaused ? (
            <button
              type="button"
              onClick={handlePauseFilling}
              disabled={!isDispensing || completionScheduledRef.current || Boolean(pauseCommandLoading)}
              className="flex min-h-11 w-full items-center justify-center gap-2 rounded-lg bg-warning px-3 py-2 text-sm font-bold text-warning-foreground transition-colors duration-200 hover:bg-warning/90 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {pauseCommandLoading === "pause" ? "Pausando..." : "Pausar llenado"}
            </button>
          ) : (
            <button
              type="button"
              onClick={handleResumeFilling}
              disabled={!isDispensing || completionScheduledRef.current || Boolean(pauseCommandLoading)}
              className="flex min-h-11 w-full items-center justify-center gap-2 rounded-lg bg-success px-3 py-2 text-sm font-bold text-success-foreground transition-colors duration-200 hover:bg-success/90 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {pauseCommandLoading === "resume" ? "Reanudando..." : "Reanudar llenado"}
            </button>
          )}
          <p className="mt-1 text-center text-xs text-text-secondary">
            {isUiPaused
              ? "Llenado pausado. Toca reanudar para continuar."
              : "Puedes pausar y reanudar cuando lo necesites."}
          </p>
        </div>

        {completionStatus ? (
          <div className="filling-status rounded-xl border border-success/20 bg-success/10 px-4 py-3 text-center text-sm font-medium text-success">
            {completionStatus}
          </div>
        ) : null}

        {displayTelemetry ? (
          <div className="filling-telemetry">
            <TelemetryStatusCard telemetry={displayTelemetry} title="Estado" compact dense />
          </div>
        ) : null}

        <div className="filling-help text-center">
          <button
            onClick={() => setIsHelpModalOpen(true)}
            className="inline-flex min-h-11 items-center space-x-2 px-5 py-2 bg-muted rounded-full hover:bg-muted/80 transition-colors duration-200"
          >
            <span className="text-body-sm font-medium text-text-primary">Ayuda</span>
          </button>
        </div>
      </main>

      <HelpModal isOpen={isHelpModalOpen} onClose={() => setIsHelpModalOpen(false)} />
      <CancelConfirmationModal
        isOpen={isCancelModalOpen}
        onClose={() => {
          if (!isCancelling) setIsCancelModalOpen(false);
        }}
        onConfirm={handleConfirmCancel}
        confirmLoading={isCancelling}
        progress={displayProgress}
        totalCost={totalCost}
        refundAmount={refundAmount}
      />
      <BottomTabNavigation isVisible={false} />
    </div>
  );
}
