// src/Routes.jsx
import React from "react";
import {
  BrowserRouter,
  Routes as RouterRoutes,
  Route,
  Navigate,
  useLocation,
} from "react-router-dom";

import ScrollToTop from "components/ScrollToTop";
import ErrorBoundary from "components/ErrorBoundary";
import NotFound from "pages/NotFound";

// 👇 reanuda intención pendiente después de login
import PendingDispenseWatcher from "components/PendingDispenseWatcher";
import DispenseSessionBoundary from "components/DispenseSessionBoundary";

import HomeDashboard from "./pages/home-dashboard";
import TransactionComplete from "./pages/transaction-complete";
import TransactionHistory from "./pages/transaction-history";
import BalanceRecharge from "./pages/balance-recharge";
import QRScannerLanding from "./pages/qr-scanner-landing";
import UserProfileSettings from "./pages/user-profile-settings";
import PromotionsCenter from "./pages/promotions-center";
import FillingProgress from "./pages/filling-progress";
import WaterMonitor from "./pages/water-monitor";
import ManagementGuard from "./components/ui/ManagementGuard";
import { AccountAccessProvider, AccountGuard } from "./components/ui/AccountAccess";
import AccountRedirect from "./pages/account-redirect";

// Flujo por pantallas
import FlowProvider from "./pages/water-dispensing-control/FlowProvider";
import WaterFlowLayout from "./pages/water-dispensing-control/WaterFlowLayout";
import SelectAmount from "./pages/water-dispensing-control/screens/SelectAmount";
import PlaceBottleDown from "./pages/water-dispensing-control/screens/PlaceBottleDown";
import PlaceBottleUp from "./pages/water-dispensing-control/screens/PlaceBottleUp";

// pública: aterrizaje desde cámara nativa
import QRResolver from "./pages/qr-resolver";

// Auth
import UserLogin from "./pages/user-login";
import UserRegistration from "./pages/user-registration";

const Protected = ({ children }) => <AccountGuard roles={["CUSTOMER"]}>{children}</AccountGuard>;

// Header (ahora mismo no pinta nada, pero respeta tus auth-routes)
function LayoutHeader() {
  const { pathname } = useLocation();
  const isAuthRoute =
    pathname.startsWith("/user-login") ||
    pathname.startsWith("/partner-login") ||
    pathname.startsWith("/user-registration");
  if (isAuthRoute) return null;
  return null;
}

// 👇 Alias para /sign-in (deep link de Clerk) -> /user-login
//    Conserva la query string: ?redirect_url=...
const SignInAlias = () => {
  const location = useLocation();
  const search = location.search || "";
  return <Navigate to={`/user-login${search}`} replace />;
};

const Routes = () => {
  return (
    <BrowserRouter>
      <ErrorBoundary>
        <AccountAccessProvider>
        <ScrollToTop />
        <LayoutHeader />

        {/* MUY IMPORTANTE: va dentro del BrowserRouter */}
        <DispenseSessionBoundary>
        <PendingDispenseWatcher />

        <RouterRoutes>
          <Route
            path="/"
            element={<AccountGuard><AccountRedirect /></AccountGuard>}
          />

          {/* ==== Auth ==== */}
          {/* Alias para deep links tipo:
              /sign-in?redirect_url=... (Clerk) */}
          <Route path="/sign-in/*" element={<SignInAlias />} />

          <Route path="/user-login/*" element={<UserLogin />} />
          <Route path="/partner-login/*" element={<UserLogin />} />
          <Route path="/user-registration/*" element={<UserRegistration />} />
          <Route path="/account-redirect" element={<AccountGuard><AccountRedirect /></AccountGuard>} />

          {/* ==== Flujo por pantallas ==== */}
          <Route
            path="/water"
            element={
              <Protected>
                <FlowProvider>
                  <WaterFlowLayout />
                </FlowProvider>
              </Protected>
            }
          >
            <Route index element={<Navigate to="choose" replace />} />
            <Route path="choose" element={<SelectAmount />} />
            <Route path="position-down" element={<PlaceBottleDown />} />
            <Route path="position-up" element={<PlaceBottleUp />} />
            {/* compat de rutas antiguas */}
            <Route path="payment" element={<Navigate to="position-up" replace />} />
          </Route>

          {/* Compatibilidad: ruta antigua */}
          <Route
            path="/water-dispensing-control"
            element={<Navigate to="/water/choose" replace />}
          />

          {/* ==== Protegidas ==== */}
          <Route
            path="/home-dashboard"
            element={
              <Protected>
                <FlowProvider>
                  <HomeDashboard />
                </FlowProvider>
              </Protected>
            }
          />

          <Route
            path="/transaction-complete"
            element={
              <Protected>
                <FlowProvider>
                  <TransactionComplete />
                </FlowProvider>
              </Protected>
            }
          />

          <Route
            path="/transaction-history"
            element={
              <Protected>
                <TransactionHistory />
              </Protected>
            }
          />

          <Route
            path="/balance-recharge"
            element={
              <Protected>
                <FlowProvider>
                  <BalanceRecharge />
                </FlowProvider>
              </Protected>
            }
          />

          <Route
            path="/water-monitor"
            element={
              <ManagementGuard>
                <FlowProvider>
                  <WaterMonitor />
                </FlowProvider>
              </ManagementGuard>
            }
          />

          <Route
            path="/partner-panel"
            element={
              <ManagementGuard>
                <FlowProvider>
                  <WaterMonitor />
                </FlowProvider>
              </ManagementGuard>
            }
          />

          <Route
            path="/promotions"
            element={
              <Protected>
                <FlowProvider>
                  <PromotionsCenter />
                </FlowProvider>
              </Protected>
            }
          />

          <Route
            path="/user-profile-settings"
            element={
              <Protected>
                <UserProfileSettings />
              </Protected>
            }
          />

          {/* Envuelve filling-progress con Provider para no perder contexto */}
          <Route
            path="/filling-progress"
            element={
              <Protected>
                <FlowProvider>
                  <FillingProgress />
                </FlowProvider>
              </Protected>
            }
          />

          {/* ==== Públicas ==== */}
          <Route path="/qr-scanner-landing" element={<QRScannerLanding />} />
          <Route path="/qr-resolver" element={<QRResolver />} />

          {/* 404 */}
          <Route path="*" element={<NotFound />} />
        </RouterRoutes>
        </DispenseSessionBoundary>
        </AccountAccessProvider>
      </ErrorBoundary>
    </BrowserRouter>
  );
};

export default Routes;
