import React, { createContext, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useAuth } from '@clerk/clerk-react';
import { showErrorToast } from '../../components/ui/NotificationToast';
import {
  DEFAULT_PULSES_PER_LITER,
  getCoinLabel,
  getTelemetryStageLabel,
  getTelemetryStepInfo,
  hexPairToDecimal,
  hexWordToDecimal,
  isActiveHexByte,
  normalizeHexPair,
  sanitizePulsesPerLiter,
} from './telemetry';

const API = import.meta.env.VITE_API_URL;
const CLERK_JWT_TEMPLATE = 'aquaqr-api';

// Caudal por defecto: 20L en 10s -> 120 L/min
const DEFAULT_FLOW_LPM = (20 / 10) * 60; // 120
const INPUT_POLL_INTERVAL_MS = 1000;
const INPUT_POLL_COOLDOWN_AFTER_COMMAND_MS = 1500;
const QR_INICIO_PENDING_WINDOW_MS = 10000;
const FLOWMETER_PULSES_PER_LITER_KEY = 'flowmeterPulsesPerLiter';
const ACTIVE_WATER_MACHINE_KEY = 'agua24.activeWaterMachine';
const DEFAULT_MONITOR_MACHINE_ID = '01';
const VALID_STAGE_CODES = new Set(['01', '02', '03', '04', '05', '06', '07', '08', '09']);
const TELEMETRY_CONNECTION_GRACE_MS = 20000;

function pulsesPerLiterStorageKey(hardwareId) {
  const normalized = normalizeHexPair(hardwareId);
  return normalized ? `${FLOWMETER_PULSES_PER_LITER_KEY}:${normalized}` : FLOWMETER_PULSES_PER_LITER_KEY;
}

function readActiveWaterMachine() {
  if (typeof window === 'undefined') return {};
  try {
    const raw = window.sessionStorage.getItem(ACTIVE_WATER_MACHINE_KEY);
    return raw ? JSON.parse(raw) || {} : {};
  } catch {
    return {};
  }
}

function writeActiveWaterMachine(machine) {
  if (typeof window === 'undefined' || !machine?.id) return;
  window.sessionStorage.setItem(ACTIVE_WATER_MACHINE_KEY, JSON.stringify({
    machineId: machine.id,
    machineLocation: machine.location,
    hardwareId: machine.hardwareId,
    at: Date.now(),
  }));
}

function extractTelemetryBytes(payload) {
  const matches = String(payload || '').toUpperCase().match(/[0-9A-F]{2}/g) || [];
  for (let index = 0; index <= matches.length - 15; index += 1) {
    const chunk = matches.slice(index, index + 15);
    if (chunk[0] === 'E2' && chunk[14] === 'E3') return chunk;
  }
  return null;
}

function parseTelemetryPayload(payload) {
  const bytes = extractTelemetryBytes(payload);
  if (!bytes) return null;

  const machineHardwareId = bytes[1];
  const phHigh = bytes[2];
  const phLow = bytes[3];
  const solidsHigh = bytes[4];
  const solidsLow = bytes[5];
  const fillValveByte = bytes[6];
  const rinseValveByte = bytes[7];
  const pumpByte = bytes[8];
  const stageByte = bytes[9];
  const flowmeterHigh = bytes[10];
  const flowmeterLow = bytes[11];
  const coinByte = bytes[12];
  const accumulatedMoneyByte = bytes[13];

  const phDecimal = hexWordToDecimal(phHigh, phLow);
  const solidsDecimal = hexWordToDecimal(solidsHigh, solidsLow);
  const flowmeterPulses = hexWordToDecimal(flowmeterHigh, flowmeterLow);
  const insertedCoinAmount = hexPairToDecimal(coinByte);
  const accumulatedMoney = hexPairToDecimal(accumulatedMoneyByte);
  const phVoltage = Number(((phDecimal * 5) / 1023).toFixed(3));
  const normalizedPumpByte = normalizeHexPair(pumpByte) || '00';
  const normalizedStageByte = normalizeHexPair(stageByte) || '00';
  const currentStageCode =
    normalizedStageByte !== '00'
      ? normalizedStageByte
      : VALID_STAGE_CODES.has(normalizedPumpByte)
        ? normalizedPumpByte
        : '00';
  const currentStepInfo = getTelemetryStepInfo(currentStageCode);
  const pumpStateByte = currentStageCode === normalizedPumpByte && normalizedStageByte === '00'
    ? '00'
    : normalizedPumpByte;

  return {
    rawFrame: bytes.join('-'),
    machineHardwareId,
    phHex: `${phHigh}-${phLow}`,
    solidsHex: `${solidsHigh}-${solidsLow}`,
    phDecimal,
    solidsDecimal,
    phVoltage,
    fillValveOn: isActiveHexByte(fillValveByte),
    rinseValveOn: isActiveHexByte(rinseValveByte),
    pumpOn: isActiveHexByte(pumpStateByte),
    pumpHex: pumpStateByte,
    currentStageCode,
    currentStageLabel: currentStepInfo.label,
    currentStageInstruction: currentStepInfo.instruction,
    flowmeterHex: `${flowmeterHigh}-${flowmeterLow}`,
    flowmeterPulses,
    coinHex: normalizeHexPair(coinByte) || '00',
    insertedCoinAmount,
    insertedCoinLabel: getCoinLabel(coinByte),
    accumulatedMoneyHex: normalizeHexPair(accumulatedMoneyByte) || '00',
    accumulatedMoney,
    receivedAt: Date.now(),
  };
}

function applyTelemetryActionSnapshot(currentTelemetry, action) {
  const nextSeenAt = Date.now();
  const withStage = (nextTelemetry, stageCode) => {
    const stepInfo = getTelemetryStepInfo(stageCode);
    return {
      ...nextTelemetry,
      currentStageCode: stepInfo.code,
      currentStageLabel: stepInfo.label,
      currentStageInstruction: stepInfo.instruction,
      lastSeenAt: nextSeenAt,
      error: '',
    };
  };

  switch (action) {
    case 'qr_inicio':
      return withStage(currentTelemetry, '01');
    case 'litros_5':
    case 'litros_10':
    case 'litros_20':
      return withStage(currentTelemetry, '03');
    case 'enjuague':
      return withStage({
        ...currentTelemetry,
        rinseValveOn: true,
      }, '04');
    case 'inicio_dispensado':
      return withStage({
        ...currentTelemetry,
        pumpOn: true,
        fillValveOn: true,
      }, '06');
    case 'valvula_llenado_on':
      return withStage({
        ...currentTelemetry,
        pumpOn: true,
        fillValveOn: true,
      }, '06');
    case 'valvula_llenado_off':
      return {
        ...currentTelemetry,
        pumpOn: false,
        fillValveOn: false,
        lastSeenAt: nextSeenAt,
        error: '',
      };
    case 'valvula_enjuague_on':
      return withStage({
        ...currentTelemetry,
        rinseValveOn: true,
      }, '04');
    case 'valvula_enjuague_off':
      return {
        ...currentTelemetry,
        rinseValveOn: false,
        lastSeenAt: nextSeenAt,
        error: '',
      };
    case 'bomba_on':
      return {
        ...currentTelemetry,
        pumpOn: true,
        lastSeenAt: nextSeenAt,
        error: '',
      };
    case 'bomba_off':
      return {
        ...currentTelemetry,
        pumpOn: false,
        lastSeenAt: nextSeenAt,
        error: '',
      };
    case 'apagar_valvulas_forzado':
      return {
        ...currentTelemetry,
        pumpOn: false,
        fillValveOn: false,
        rinseValveOn: false,
        lastSeenAt: nextSeenAt,
        error: '',
      };
    case 'reiniciar_sistema':
      return withStage({
        ...currentTelemetry,
        pumpOn: false,
        fillValveOn: false,
        rinseValveOn: false,
      }, '00');
    default:
      return currentTelemetry;
  }
}

const Ctx = createContext(null);
export const useDispenseFlow = () => useContext(Ctx);

export default function FlowProvider({ children }) {
  const { getToken, userId } = useAuth();
  const location = useLocation();
  const routeState = location.state || {};

  const machineFromRoute = useMemo(() => {
    const storedMachine = readActiveWaterMachine();
    const fallbackId = DEFAULT_MONITOR_MACHINE_ID;
    const rawRouteMachineId = String(routeState.machineId || '').trim();
    const routeHardwareId = normalizeHexPair(routeState.hardwareId);
    const storedHardwareId = normalizeHexPair(storedMachine.hardwareId);
    const shouldPreferStoredMachine =
      storedMachine.machineId
      && storedHardwareId
      && (!rawRouteMachineId || normalizeHexPair(rawRouteMachineId) !== storedHardwareId)
      && (!routeHardwareId || routeHardwareId === storedHardwareId);
    const machineId = String(
      shouldPreferStoredMachine
        ? storedMachine.machineId
        : rawRouteMachineId || storedMachine.machineId || fallbackId
    ).trim();
    const machineLocation = String(
      routeState.machineLocation
      || storedMachine.machineLocation
      || 'Centro Comercial Plaza Norte, Local 15'
    ).trim();

    // Cuando el ID es una trama tipo E2-01-01-...-E3, el segundo byte suele ser
    // el identificador de hardware que usa la telemetria.
    const frameBytes = machineId.toUpperCase().match(/[0-9A-F]{2}/g) || [];
    const compactMachineHardwareId = machineId.toUpperCase().replace(/[^0-9A-F]/g, '');
    const inferredHardwareId =
      frameBytes.length >= 3 && frameBytes[0] === 'E2' && frameBytes[frameBytes.length - 1] === 'E3'
        ? frameBytes[1]
        : compactMachineHardwareId
          ? normalizeHexPair(compactMachineHardwareId)
        : null;

    const finalHardwareId = String(
      routeState.hardwareId
      || storedMachine.hardwareId
      || inferredHardwareId
      || DEFAULT_MONITOR_MACHINE_ID
    ).trim();
    const finalMachineId =
      normalizeHexPair(machineId) !== normalizeHexPair(finalHardwareId)
        ? (storedMachine.machineId || `00${normalizeHexPair(finalHardwareId) || machineId}`.slice(-3))
        : machineId;

    return {
      id: finalMachineId,
      location: machineLocation,
      hardwareId: finalHardwareId,
    };
  }, [routeState.hardwareId, routeState.machineId, routeState.machineLocation]);

  const qrStartFromRouteAt = useMemo(() => {
    if (!routeState.qrInicioSent) return null;
    const sentAt = Number(routeState.qrInicioSentAt);
    if (Number.isFinite(sentAt)) {
      return Date.now() - sentAt <= QR_INICIO_PENDING_WINDOW_MS ? sentAt : null;
    }
    return Date.now();
  }, [routeState.qrInicioSent, routeState.qrInicioSentAt]);

  const [machine, setMachine] = useState(machineFromRoute);

  const [connectionStatus, setConnectionStatus] = useState('connecting'); // connecting | connected | disconnected
  const [isVerified, setIsVerified] = useState(false);

  const [allowedLiters, setAllowedLiters] = useState([5, 10, 20]);
  const [pricePerLiterCents, setPricePerLiterCents] = useState(175);
  const pricePerLiter = useMemo(() => (pricePerLiterCents || 0) / 100, [pricePerLiterCents]);

  const [selectedLiters, setSelectedLiters] = useState(20);
  const [balanceCents, setBalanceCents] = useState(null);
  const [pulsesPerLiter, setPulsesPerLiterState] = useState(() => {
    if (typeof window === 'undefined') return DEFAULT_PULSES_PER_LITER;
    return sanitizePulsesPerLiter(window.localStorage.getItem(pulsesPerLiterStorageKey(machineFromRoute.hardwareId)));
  });

  const [lastTx, setLastTx] = useState(null);
  const [hasActiveSession, setHasActiveSession] = useState(() => (
    Boolean(routeState.fromActiveSession || routeState.tx || qrStartFromRouteAt)
  ));
  const [pendingQrStartAt, setPendingQrStartAt] = useState(() => qrStartFromRouteAt);
  const [telemetry, setTelemetry] = useState({
    status: 'idle',
    rawResponse: '',
    rawFrame: '',
    machineHardwareId: null,
    phHex: '',
    solidsHex: '',
    phDecimal: null,
    solidsDecimal: null,
    phVoltage: null,
    fillValveOn: false,
    rinseValveOn: false,
    pumpOn: false,
    pumpHex: '00',
    currentStageCode: '00',
    currentStageLabel: getTelemetryStageLabel('00'),
    currentStageInstruction: getTelemetryStepInfo('00').instruction,
    flowmeterHex: '',
    flowmeterPulses: null,
    coinHex: '00',
    insertedCoinAmount: 0,
    insertedCoinLabel: 'Sin moneda',
    accumulatedMoneyHex: '00',
    accumulatedMoney: 0,
    machineOnline: false,
    lastSeenAt: null,
    error: '',
  });
  const telemetryRef = useRef(telemetry);
  const [telemetryEnabled, setTelemetryEnabled] = useState(false);
  const [coinRechargeSyncEnabled, setCoinRechargeSyncEnabled] = useState(false);
  const [machineCoinsEnabled, setMachineCoinsEnabled] = useState(false);
  const pollingRef = useRef(false);
  const pollingCooldownUntilRef = useRef(0);
  const telemetryCreditSyncRef = useRef('');
  const commandInFlightRef = useRef(false);
  const startDispenseInFlightRef = useRef(false);
  const cancelActiveSessionPromiseRef = useRef(null);
  const lastGuidedStageCodeRef = useRef('00');
  const authOwnerRef = useRef(userId || null);
  const walletRevision = useRef(0);
  const isDocumentVisible = () => typeof document === 'undefined' || document.visibilityState === 'visible';

  useEffect(() => {
    telemetryRef.current = telemetry;
  }, [telemetry]);

  useEffect(() => {
    const updated = (event) => {
      if (event.detail?.userId && event.detail.userId !== userId) return;
      if (Number.isFinite(event.detail?.balanceCents)) {
        walletRevision.current++; setBalanceCents(event.detail.balanceCents);
      }
    };
    window.addEventListener('wallet:updated', updated);
    return () => window.removeEventListener('wallet:updated', updated);
  }, [userId]);

  const setPulsesPerLiter = (value) => {
    const nextValue = sanitizePulsesPerLiter(value);
    setPulsesPerLiterState(nextValue);
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(pulsesPerLiterStorageKey(machine.hardwareId), String(nextValue));
    }
    return nextValue;
  };

  useEffect(() => {
    setMachine(machineFromRoute);
    setMachineCoinsEnabled(false);
    writeActiveWaterMachine(machineFromRoute);
    if (typeof window !== 'undefined') {
      setPulsesPerLiterState(sanitizePulsesPerLiter(
        window.localStorage.getItem(pulsesPerLiterStorageKey(machineFromRoute.hardwareId)),
        DEFAULT_PULSES_PER_LITER,
      ));
    }
  }, [machineFromRoute]);

  useEffect(() => {
    const routeLiters = Number(routeState.selectedLiters);
    if (Number.isFinite(routeLiters) && routeLiters > 0) {
      setSelectedLiters(routeLiters);
    }
  }, [routeState.selectedLiters]);

  useEffect(() => {
    if (routeState.fromActiveSession || routeState.tx || qrStartFromRouteAt) {
      setHasActiveSession(true);
    }
  }, [qrStartFromRouteAt, routeState.fromActiveSession, routeState.tx]);

  useEffect(() => {
    if (!qrStartFromRouteAt) return;
    setPendingQrStartAt((current) => (current && current >= qrStartFromRouteAt ? current : qrStartFromRouteAt));
  }, [qrStartFromRouteAt]);

  useEffect(() => {
    if (authOwnerRef.current === userId) return;

    authOwnerRef.current = userId || null;
    walletRevision.current++; setBalanceCents(null);
    setMachine(machineFromRoute);
    setSelectedLiters(Number.isFinite(Number(routeState.selectedLiters)) && Number(routeState.selectedLiters) > 0
      ? Number(routeState.selectedLiters)
      : 20);
    setLastTx(null);
    setHasActiveSession(Boolean(routeState.fromActiveSession || routeState.tx || qrStartFromRouteAt));
    setPendingQrStartAt(qrStartFromRouteAt);
    setTelemetryEnabled(false);
    setCoinRechargeSyncEnabled(false);
    setTelemetry({
      status: 'idle',
      rawResponse: '',
      rawFrame: '',
      machineHardwareId: null,
      phHex: '',
      solidsHex: '',
      phDecimal: null,
      solidsDecimal: null,
      phVoltage: null,
      fillValveOn: false,
      rinseValveOn: false,
      pumpOn: false,
      pumpHex: '00',
      currentStageCode: '00',
      currentStageLabel: getTelemetryStageLabel('00'),
      currentStageInstruction: getTelemetryStepInfo('00').instruction,
      flowmeterHex: '',
      flowmeterPulses: null,
      coinHex: '00',
      insertedCoinAmount: 0,
      insertedCoinLabel: 'Sin moneda',
      accumulatedMoneyHex: '00',
      accumulatedMoney: 0,
      machineOnline: false,
      lastSeenAt: null,
      error: '',
    });
    pollingRef.current = false;
    pollingCooldownUntilRef.current = 0;
    telemetryCreditSyncRef.current = '';
    commandInFlightRef.current = false;
    startDispenseInFlightRef.current = false;
    cancelActiveSessionPromiseRef.current = null;
    lastGuidedStageCodeRef.current = '00';
  }, [machineFromRoute, qrStartFromRouteAt, routeState.fromActiveSession, routeState.selectedLiters, routeState.tx, userId]);

  // Simula conexión y verificación breve
  useEffect(() => {
    const t = setTimeout(() => {
      setConnectionStatus('connected');
      setIsVerified(true);
    }, 800);
    return () => clearTimeout(t);
  }, []);

  async function fetchConfig() {
    try {
      const query = new URLSearchParams();
      if (machine.hardwareId) query.set('hardwareId', machine.hardwareId);
      if (machine.id) query.set('machineId', machine.id);
      const res = await fetch(`${API}/api/dispense/config${query.toString() ? `?${query}` : ''}`);
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'No se pudo obtener config');

      setPricePerLiterCents(data.pricePerLiterCents ?? 175);
      setMachineCoinsEnabled(data.coinsEnabled === true);
      const nextPulsesPerLiter = sanitizePulsesPerLiter(
        data.pulsesPerLiter ?? data.defaultPulsesPerLiter,
        pulsesPerLiter,
      );
      setPulsesPerLiter(nextPulsesPerLiter);
      const nextAllowedLiters = data.allowedLiters ?? data.optionsLiters ?? [5, 10, 20];
      setAllowedLiters(nextAllowedLiters);

      if (!nextAllowedLiters.includes(selectedLiters)) {
        setSelectedLiters(nextAllowedLiters[0]);
      }
    } catch (e) {
      showErrorToast(e.message || 'Error cargando configuración');
    }
  }

  async function fetchWallet() {
    const revision = walletRevision.current, owner = userId;
    try {
      const token = await getToken({ template: CLERK_JWT_TEMPLATE });
      const res = await fetch(`${API}/api/me/wallet`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'No se pudo obtener el saldo');
      if (authOwnerRef.current !== owner || walletRevision.current !== revision) return;
      if (typeof data?.balanceCents === 'number') {
        setBalanceCents(data.balanceCents);
        window.dispatchEvent(new CustomEvent('wallet:updated', {
          detail: {
            balanceCents: data.balanceCents,
            realBalanceCents: data.realBalanceCents,
            bonusBalanceCents: data.bonusBalanceCents,
            source: 'wallet-fetch',
            userId: owner,
          },
        }));
      }
    } catch (e) {
      showErrorToast(e.message || 'Error cargando saldo');
    }
  }

  async function pollInputs(options = {}) {
    const force = options?.force === true;

    if (!force && !telemetryEnabled) return;
    if (!isDocumentVisible()) return;
    if (!force && Date.now() < pollingCooldownUntilRef.current) return;
    if (pollingRef.current) return force ? telemetryRef.current : undefined;
    pollingRef.current = true;

    try {
      const token = await getToken({ template: CLERK_JWT_TEMPLATE });
      const monitorQuery = new URLSearchParams();
      if (machine?.hardwareId) monitorQuery.set('hardwareId', machine.hardwareId);
      if (machine?.id) monitorQuery.set('machineId', machine.id);
      const monitorUrl = `${API}/api/dispense/demo/monitor${monitorQuery.toString() ? `?${monitorQuery}` : ''}`;
      const res = await fetch(monitorUrl, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.detail || data?.error || 'No se pudo leer monitor');

      if (data?.reconnecting || data?.connected === false) {
        const previousTelemetry = telemetryRef.current;
        const previousAgeMs = previousTelemetry?.lastSeenAt ? Date.now() - previousTelemetry.lastSeenAt : Infinity;
        if (previousTelemetry?.machineOnline && previousAgeMs <= TELEMETRY_CONNECTION_GRACE_MS) {
          const toleratedTelemetry = {
            ...previousTelemetry,
            status: 'reconnecting',
            error: data?.message || 'Reconectando maquina...',
          };
          setTelemetry(toleratedTelemetry);
          return toleratedTelemetry;
        }

        setTelemetry((prev) => ({
          ...prev,
          status: 'reconnecting',
          machineOnline: false,
          error: data?.message || 'Reconectando maquina...',
        }));
        return null;
      }

      const serverTelemetry = data?.telemetry || null;
      const rawResponse = [
        serverTelemetry?.rawFrame,
        data?.response,
        ...(data?.lines || []),
      ].filter(Boolean).join(' ');
      const parsed = parseTelemetryPayload(rawResponse);

      if (!parsed) {
        setTelemetry((prev) => ({
          ...prev,
          status: 'error',
          rawResponse,
          error: 'No se pudo interpretar la trama del sensor',
        }));
        return;
      }

      const parsedHardwareId = normalizeHexPair(parsed.machineHardwareId);
      const responseHardwareId =
        normalizeHexPair(data?.hardwareId)
        || normalizeHexPair(data?.waterserver?.hardwareId)
        || parsedHardwareId;
      const expectedMachineId = normalizeHexPair(machine.hardwareId);
      const machineOnline = Boolean(parsedHardwareId && (!responseHardwareId || parsedHardwareId === responseHardwareId));

      if (parsedHardwareId && expectedMachineId !== parsedHardwareId) {
        setMachine((currentMachine) => {
          const nextMachine = {
            ...currentMachine,
            id: `00${parsedHardwareId}`.slice(-3),
            hardwareId: parsedHardwareId,
          };
          writeActiveWaterMachine(nextMachine);
          return nextMachine;
        });
      }

      const serverStageCode = normalizeHexPair(serverTelemetry?.currentStageCode);
      const effectiveStageCode = serverStageCode || parsed.currentStageCode;
      const effectiveStepInfo = getTelemetryStepInfo(effectiveStageCode);

      const nextTelemetry = {
        status: 'ok',
        rawResponse,
        rawFrame: parsed.rawFrame,
        machineHardwareId: parsed.machineHardwareId,
        phHex: parsed.phHex,
        solidsHex: parsed.solidsHex,
        phDecimal: parsed.phDecimal,
        solidsDecimal: parsed.solidsDecimal,
        phVoltage: parsed.phVoltage,
        fillValveOn: parsed.fillValveOn,
        rinseValveOn: parsed.rinseValveOn,
        pumpOn: parsed.pumpOn,
        pumpHex: parsed.pumpHex,
        currentStageCode: effectiveStepInfo.code,
        currentStageLabel: effectiveStepInfo.label,
        currentStageInstruction: effectiveStepInfo.instruction,
        flowmeterHex: parsed.flowmeterHex,
        flowmeterPulses: parsed.flowmeterPulses,
        coinHex: parsed.coinHex,
        insertedCoinAmount: parsed.insertedCoinAmount,
        insertedCoinLabel: parsed.insertedCoinLabel,
        accumulatedMoneyHex: parsed.accumulatedMoneyHex,
        accumulatedMoney: parsed.accumulatedMoney,
        machineOnline,
        lastSeenAt: parsed.receivedAt,
        error: '',
      };

      setTelemetry(nextTelemetry);
      return nextTelemetry;
    } catch (e) {
      const previousTelemetry = telemetryRef.current;
      const previousAgeMs = previousTelemetry?.lastSeenAt ? Date.now() - previousTelemetry.lastSeenAt : Infinity;
      if (previousTelemetry?.machineOnline && previousAgeMs <= TELEMETRY_CONNECTION_GRACE_MS) {
        const toleratedTelemetry = {
          ...previousTelemetry,
          status: 'reconnecting',
          error: e.message || 'Reconectando maquina...',
        };
        setTelemetry(toleratedTelemetry);
        return toleratedTelemetry;
      }

      setTelemetry((prev) => ({
        ...prev,
        status: 'error',
        error: e.message || 'Error leyendo inputs',
      }));
      return null;
    } finally {
      pollingRef.current = false;
    }
  }

  async function sendStageCommand(action, options = {}) {
    if (commandInFlightRef.current) {
      throw new Error('Espera a que termine el comando anterior');
    }

    commandInFlightRef.current = true;
    let previousTelemetry = null;
    const previousPendingQrStartAt = pendingQrStartAt;

    setTelemetry((currentTelemetry) => {
      previousTelemetry = currentTelemetry;
      return applyTelemetryActionSnapshot(currentTelemetry, action);
    });
    if (action === 'qr_inicio') {
      setPendingQrStartAt(Date.now());
    }

    const token = await getToken({ template: CLERK_JWT_TEMPLATE });
    try {
      const commandPulsesPerLiter = sanitizePulsesPerLiter(
        options?.pulsesPerLiter ?? pulsesPerLiter,
        pulsesPerLiter,
      );
      pollingCooldownUntilRef.current = Date.now() + INPUT_POLL_COOLDOWN_AFTER_COMMAND_MS;
      const res = await fetch(`${API}/api/dispense/demo/control`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          action,
          machineId: machine.id,
          machineLocation: machine.location,
          hardwareId: machine.hardwareId,
          pulsesPerLiter: commandPulsesPerLiter,
        }),
      });
      const data = await res.json();
      if (res.status === 423 && data?.error === 'MACHINE_BUSY') {
        const err = new Error(data?.message || 'Esta maquina esta en uso por otro usuario');
        err.code = 'MACHINE_BUSY';
        err.expiresAt = data?.expiresAt;
        err.isOwnLock = data?.isOwnLock;
        throw err;
      }
      if (data?.reconnecting || data?.error === 'WATERSERVER_RECONNECTING') {
        const err = new Error(data?.message || 'La maquina se esta reconectando. Intenta de nuevo en unos segundos.');
        err.code = 'WATERSERVER_RECONNECTING';
        err.reconnecting = true;
        throw err;
      }
      if (!res.ok) throw new Error(data?.detail || data?.message || data?.error || `No se pudo enviar ${action}`);
      if (action !== 'inputs' && action !== 'recargar' && action !== 'recarga_monedas') {
        setHasActiveSession(true);
      }
      return data;
    } catch (error) {
      if (previousTelemetry) {
        setTelemetry(previousTelemetry);
      }
      if (action === 'qr_inicio') {
        setPendingQrStartAt(previousPendingQrStartAt);
      }
      throw error;
    } finally {
      commandInFlightRef.current = false;
    }
  }

  async function syncTelemetryCredit(nextTelemetry, options = {}) {
    const insertedAmount = Number.parseInt(nextTelemetry?.insertedCoinAmount, 10);
    const accumulatedAmount = Number.parseInt(nextTelemetry?.accumulatedMoney, 10);
    const pulseCount = Number.parseInt(nextTelemetry?.flowmeterPulses, 10);
    const rawFrame = String(nextTelemetry?.rawFrame || '').trim();
    const hasInsertedAmount = Number.isFinite(insertedAmount) && insertedAmount >= 0;
    const hasAccumulatedAmount = Number.isFinite(accumulatedAmount) && accumulatedAmount >= 0;

    if (!rawFrame) return;
    if (!hasInsertedAmount && !hasAccumulatedAmount) return;

    const machineId =
      normalizeHexPair(nextTelemetry?.machineHardwareId) ||
      normalizeHexPair(machine?.hardwareId) ||
      String(machine?.id || 'UNKNOWN').trim().toUpperCase();

    const syncKey = `${machineId}:${rawFrame}`;
    if (!options.force && telemetryCreditSyncRef.current === syncKey) return null;
    telemetryCreditSyncRef.current = syncKey;

    try {
      const token = await getToken({ template: CLERK_JWT_TEMPLATE });
      const res = await fetch(`${API}/api/recharge/telemetry-credit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          machineId,
          insertedAmount: hasInsertedAmount ? insertedAmount : 0,
          accumulatedAmount: hasAccumulatedAmount ? accumulatedAmount : undefined,
          pulseCount,
          rawFrame,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        throw new Error(data?.detail || data?.error || 'No se pudo sincronizar la recarga por telemetria');
      }

      if (typeof data?.balanceCents === 'number') {
        setBalanceCents(data.balanceCents);
        window.dispatchEvent(new CustomEvent('wallet:updated', {
          detail: {
            balanceCents: data.balanceCents,
            realBalanceCents: data.realBalanceCents,
            bonusBalanceCents: data.bonusBalanceCents,
            source: 'telemetry',
            machineId,
          },
        }));
      }

      return data;
    } catch (error) {
      telemetryCreditSyncRef.current = '';
      console.error('syncTelemetryCredit error', error);
      throw error;
    }
  }

  function resetTelemetryCreditSync() {
    telemetryCreditSyncRef.current = '';
  }

  // Inicia el llenado en la maquina. El cobro se confirma al finalizar.
  async function startDispense() {
    if (startDispenseInFlightRef.current) {
      throw new Error('El llenado ya se esta iniciando');
    }

    startDispenseInFlightRef.current = true;
    try {
    const token = await getToken({ template: CLERK_JWT_TEMPLATE });
    const res = await fetch(`${API}/api/dispense`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify({
        liters: selectedLiters,
        machineId: machine.id,
        hardwareId: machine.hardwareId,
        location: machine.location,
        pulsesPerLiter,
      }),
    });
    const data = await res.json();

    if (res.status === 423 && data?.error === 'MACHINE_BUSY') {
      const err = new Error(data?.message || 'Esta maquina esta en uso por otro usuario');
      err.code = 'MACHINE_BUSY';
      err.expiresAt = data?.expiresAt;
      err.isOwnLock = data?.isOwnLock;
      throw err;
    }

    if (res.status === 400 && data?.error === 'INSUFFICIENT_FUNDS') {
      const requiredAmount = Math.max(0, (data.neededCents ?? ((data.payableCents ?? data.totalCents ?? data.amountCents) - data.balanceCents)) / 100);
      const err = new Error('INSUFFICIENT_FUNDS');
      err.code = 'INSUFFICIENT_FUNDS';
      err.requiredAmount = requiredAmount;
      throw err;
    }
    if (!res.ok) throw new Error(data?.error || 'No se pudo iniciar el dispensado');

    const amountCents = data.payableCents ?? data.amountCents ?? Math.round(selectedLiters * pricePerLiter * 100);
    const newBalanceCents = data.newBalanceCents ?? data.balanceCents ?? balanceCents;
    const prevBalanceCents = data.prevBalanceCents ?? balanceCents;

    const tx = {
      at: Date.now(),
      liters: selectedLiters,
      pricePerLiter,
      amountCents,
      membershipCoveredLiters: data.membershipCoveredLiters || 0,
      prevBalanceCents,
      newBalanceCents,
      machineId: machine.id,
      location: machine.location,
      startPulseCount: Number.parseInt(telemetry?.flowmeterPulses, 10) || 0,
      pulsesPerLiter,
      // ⬇️ Caudal real si viene del backend o 120 L/min por defecto
      flowRateLpm: data.flowRateLpm ?? DEFAULT_FLOW_LPM,
      txId: data.txId,
    };

    setLastTx(tx);
    setHasActiveSession(true);
    setPendingQrStartAt(null);
    setTelemetry((currentTelemetry) => applyTelemetryActionSnapshot(currentTelemetry, 'inicio_dispensado'));
    return tx;
    } finally {
      startDispenseInFlightRef.current = false;
    }
  }

  async function completeDispense(tx, completion = {}) {
    const txId = tx?.txId;
    if (!txId) throw new Error('No se encontro la transaccion de dispensado');

    const token = await getToken({ template: CLERK_JWT_TEMPLATE });
    const res = await fetch(`${API}/api/dispense/complete`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify({
        txId,
        dispensedLiters: completion.dispensedLiters,
        dispensedPulseCount: completion.dispensedPulseCount,
        pulsesPerLiter: completion.pulsesPerLiter,
      }),
    });
    const data = await res.json();

    if (res.status === 400 && data?.error === 'INSUFFICIENT_FUNDS') {
      const requiredAmount = Math.max(0, (data.neededCents ?? ((data.payableCents ?? data.totalCents) - data.balanceCents)) / 100);
      const err = new Error('INSUFFICIENT_FUNDS');
      err.code = 'INSUFFICIENT_FUNDS';
      err.requiredAmount = requiredAmount;
      throw err;
    }
    if (!res.ok) throw new Error(data?.error || 'No se pudo completar el cobro');

    const completedTx = {
      ...tx,
      completedAt: Date.now(),
      amountCents: data.amountCents ?? tx.amountCents,
      membershipCoveredLiters: data.membershipCoveredLiters ?? tx.membershipCoveredLiters,
      newBalanceCents: data.newBalanceCents ?? tx.newBalanceCents,
      status: data.status || 'COMPLETED',
      ledgerId: data.ledgerId,
      ...completion,
    };

    if (typeof data?.newBalanceCents === 'number') {
      setBalanceCents(data.newBalanceCents);
      window.dispatchEvent(new CustomEvent('wallet:updated', {
        detail: {
          balanceCents: data.newBalanceCents,
          realBalanceCents: data.realBalanceCents,
          bonusBalanceCents: data.bonusBalanceCents,
          source: 'dispense',
          machineId: machine.id,
        },
      }));
    }

    setLastTx(completedTx);
    setHasActiveSession(false);
    setPendingQrStartAt(null);
    return completedTx;
  }

  async function cancelActiveSession() {
    if (cancelActiveSessionPromiseRef.current) {
      return cancelActiveSessionPromiseRef.current;
    }

    cancelActiveSessionPromiseRef.current = (async () => {
      const token = await getToken({ template: CLERK_JWT_TEMPLATE });
      const res = await fetch(`${API}/api/dispense/active/cancel`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ pulsesPerLiter }),
      });
      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        const error = new Error(data?.message || data?.error || 'No se pudo cancelar el proceso');
        error.code = data?.error;
        throw error;
      }

      setLastTx(null);
      setHasActiveSession(false);
      setPendingQrStartAt(null);
      setTelemetry((currentTelemetry) => applyTelemetryActionSnapshot(currentTelemetry, 'reiniciar_sistema'));

      if (typeof data?.balanceCents === 'number') {
        setBalanceCents(data.balanceCents);
        window.dispatchEvent(new CustomEvent('wallet:updated', {
          detail: {
            balanceCents: data.balanceCents,
            source: 'dispense-cancel',
            machineId: machine.id,
          },
        }));
      }

      return data;
    })();

    try {
      return await cancelActiveSessionPromiseRef.current;
    } finally {
      cancelActiveSessionPromiseRef.current = null;
    }
  }

  useEffect(() => {
    const currentStageCode = telemetry.currentStageCode || '00';
    if (currentStageCode !== '00' || lastTx?.txId) {
      setPendingQrStartAt(null);
    }
  }, [lastTx?.txId, telemetry.currentStageCode]);

  const hasStartedDispenseTx = Boolean(lastTx?.txId || location.state?.tx?.txId);
  const hasPendingQrStart =
    Number.isFinite(pendingQrStartAt) && Date.now() - pendingQrStartAt < QR_INICIO_PENDING_WINDOW_MS;
  const rawStageCode = telemetry.currentStageCode || '00';
  const previousGuidedStageCode = lastGuidedStageCodeRef.current || '00';
  const isManualActuatorStage =
    !hasStartedDispenseTx
    && !hasActiveSession
    && !hasPendingQrStart
    && (
      rawStageCode === '06'
      || (rawStageCode === '04' && !['03', '04'].includes(previousGuidedStageCode))
      || (rawStageCode === '05' && !['04', '05'].includes(previousGuidedStageCode))
    );

  const guidedStageCode = isManualActuatorStage ? previousGuidedStageCode : rawStageCode;
  if (!isManualActuatorStage) {
    lastGuidedStageCodeRef.current = guidedStageCode;
  }
  const guidedStepInfo = getTelemetryStepInfo(guidedStageCode);
  const guidedTelemetry = isManualActuatorStage
    ? {
        ...telemetry,
        currentStageCode: guidedStepInfo.code,
        currentStageLabel: guidedStepInfo.label,
        currentStageInstruction: guidedStepInfo.instruction,
        rawStageCode,
      }
    : telemetry;

  const value = {
    machine,
    connectionStatus,
    isVerified,
    allowedLiters,
    pricePerLiter,
    pricePerLiterCents,
    selectedLiters,
    setSelectedLiters,
    balanceCents,
    pulsesPerLiter,
    setPulsesPerLiter,
    lastTx,
    hasActiveSession,
    hasPendingQrStart,
    telemetry,
    guidedTelemetry,
    telemetryEnabled,
    setTelemetryEnabled,
    coinRechargeSyncEnabled,
    setCoinRechargeSyncEnabled,
    fetchConfig,
    fetchWallet,
    pollInputs,
    syncTelemetryCredit,
    resetTelemetryCreditSync,
    sendStageCommand,
    startDispense,
    completeDispense,
    cancelActiveSession,
  };

  useEffect(() => {
    let intervalId = 0;
    let cancelled = false;

    const startPolling = async () => {
      if (!telemetryEnabled) return;
      try {
        if (isDocumentVisible()) {
          await pollInputs();
        }
      } catch {
        // pollInputs already persists errors in state.
      }

      if (cancelled) return;
      intervalId = window.setInterval(() => {
        if (isDocumentVisible()) {
          pollInputs();
        }
      }, INPUT_POLL_INTERVAL_MS);
    };

    const handleVisibilityChange = () => {
      if (telemetryEnabled && isDocumentVisible()) {
        pollInputs().catch(() => {});
      }
    };

    startPolling();
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      cancelled = true;
      if (intervalId) window.clearInterval(intervalId);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [telemetryEnabled]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const ownCoinSession = machineCoinsEnabled && hasActiveSession
      && (location.pathname.startsWith('/water/') || location.pathname === '/filling-progress');
    if (!telemetryEnabled || !(coinRechargeSyncEnabled || ownCoinSession)) return;
    if (!telemetry?.rawFrame) return;

    syncTelemetryCredit(telemetry).catch(() => {});
  }, [coinRechargeSyncEnabled, machineCoinsEnabled, hasActiveSession, location.pathname, telemetryEnabled, telemetry]); // eslint-disable-line react-hooks/exhaustive-deps

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}
